"""
Module to calculate the average of a list of numbers.
"""

def calculate_average(numbers: list[float]) -> float | None:
    """
    Calculate the average of a list of numbers.

    Args:
        numbers: A list of numbers.

    Returns:
        The average of the numbers in the list, or None if the list is empty.
    """
    if not numbers:
        return None
    if not all(isinstance(x, (int, float)) for x in numbers):
        raise TypeError("Input list must contain only numbers")
    return sum(numbers) / len(numbers)

